// ========================================
// User & Auth Types
// ========================================

export interface User {
  id?: string;
  username: string;
  email: string;
  role: string;
  roles: string[];
}

export interface Role {
  id: string;
  name: string;
  analysis: boolean;
  index: boolean;
  search: boolean;
  manage: boolean;
  inUse: boolean;
}

// ========================================
// Cluster Types
// ========================================

export interface Cluster {
  id: string;
  name: string;
  host: string;
  port: number;
  scheme: 'http' | 'https';
  username?: string;
  password?: string;
  kibana?: string;
  theme: ClusterTheme;
  nodeCount: number;
  indexCount: number;
  shardCount: number;
  docCount?: number;
  storeSize: string;
  status: HealthStatus;
  dictCluster?: string;
  serverCheck?: boolean;
}

export type ClusterTheme = 'dark' | 'light' | 'blue' | 'green' | 'indigo' | 'teal';
export type HealthStatus = 'green' | 'yellow' | 'red';

export interface ClusterHealth {
  cluster_name: string;
  status: HealthStatus;
  timed_out: boolean;
  number_of_nodes: number;
  number_of_data_nodes: number;
  active_primary_shards: number;
  active_shards: number;
  relocating_shards: number;
  initializing_shards: number;
  unassigned_shards: number;
  delayed_unassigned_shards: number;
  number_of_pending_tasks: number;
  number_of_in_flight_fetch: number;
  task_max_waiting_in_queue_millis: number;
  active_shards_percent_as_number: number;
}

export interface ClusterStats {
  nodes: {
    count: {
      total: number;
      data: number;
      master: number;
      ingest: number;
    };
  };
  indices: {
    count: number;
    shards: {
      total: number;
      primaries: number;
    };
    docs: {
      count: number;
      deleted: number;
    };
    store: {
      size_in_bytes: number;
    };
  };
}

export interface ClusterNode {
  id: string;
  name: string;
  ip: string;
  roles: string[];
  master: boolean;
  heap: {
    percent: number;
    max: string;
    used: string;
  };
  cpu: number;
  load: string;
  diskUsed: string;
  diskTotal: string;
  diskPercent: number;
}

export interface ClusterSettings {
  persistent: Record<string, unknown>;
  transient: Record<string, unknown>;
  defaults: Record<string, unknown>;
}

// ========================================
// Index Types
// ========================================

export interface Index {
  health: HealthStatus;
  status: 'open' | 'close';
  index: string;
  uuid: string;
  pri: string;
  rep: string;
  docsCount: string;
  docsDeleted: string;
  storeSize: string;
  priStoreSize: string;
  frozen?: boolean;
  aliases?: string[];
}

export interface IndexDetail {
  index: string;
  health: HealthStatus;
  status: 'open' | 'close';
  frozen: boolean;
  pri: number;
  rep: number;
  docsCount: number;
  docsDeleted: number;
  storeSize: string;
  priStoreSize: string;
  aliases: string[];
  mappings: IndexMappings;
  settings: IndexSettings;
}

export interface IndexMappings {
  properties: Record<string, MappingProperty>;
}

export interface MappingProperty {
  type: string;
  index?: boolean;
  analyzer?: string;
  search_analyzer?: string;
  copy_to?: string | string[];
  ignore_above?: number;
  null_value?: string;
  doc_values?: boolean;
  similarity?: string;
